arguments.cmd:
mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Leap Studio — Reinvention & Experience Partner</title>
  <meta name="description" content="Leap Studio is a global creative agency helping enterprise teams reinvent experiences through strategy, design, and technology." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #0a0a0a;
      --surface: #101114;
      --surface-2: #17181d;
      --text: #f4f5f7;
      --muted: #a1a6b3;
      --line: #252833;
      --accent: #4da3ff;
      --accent-2: #ffb454;
      --max: 1240px;
      --r-lg: 22px;
      --r-md: 16px;
      --r-sm: 12px;
      --shadow: 0 24px 50px rgba(0,0,0,.35);
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
      background: radial-gradient(1200px 700px at 80% -10%, rgba(77,163,255,.12), transparent 65%), var(--bg);
      color: var(--text);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }

    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }
    .container { width: min(var(--max), calc(100% - 2.5rem)); margin-inline: auto; }
    .section { padding: 5.5rem 0; }
    .eyebrow { letter-spacing: .14em; text-transform: uppercase; font-size: .74rem; color: var(--muted); }
    .h2 { font-size: clamp(1.9rem, 1.2rem + 2vw, 3rem); line-height: 1.15; margin: .75rem 0 1rem; }
    .lead { max-width: 68ch; color: #c4c8d1; }

    .header {
      position: sticky; top: 0; z-index: 60;
      backdrop-filter: blur(12px);
      background: linear-gradient(to bottom, rgba(10,10,10,.92), rgba(10,10,10,.72));
      border-bottom: 1px solid rgba(255,255,255,.06);
    }
    .nav { display: flex; align-items: center; justify-content: space-between; min-height: 78px; gap: 1rem; }
    .brand { display: flex; align-items: center; gap: .65rem; font-weight: 700; letter-spacing: .01em; }
    .brand-mark {
      width: 30px; height: 30px; border-radius: 10px;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      box-shadow: 0 0 0 1px rgba(255,255,255,.2) inset;
    }

    .nav-links { display: flex; gap: 1.3rem; align-items: center; }
    .nav-links a {
      font-size: .94rem;
      color: #d2d6df;
      transition: color .2s ease;
      padding: .3rem 0;
    }
    .nav-links a:hover, .nav-links a:focus-visible { color: #fff; }

    .lang-wrap { position: relative; }
    .lang-btn, .btn {
      border: 1px solid rgba(255,255,255,.16);
      background: #121318;
      color: #e9ecf3;
      padding: .65rem .9rem;
      border-radius: 999px;
      font-weight: 500;
      cursor: pointer;
      transition: .22s ease;
      min-height: 44px;
    }
    .lang-btn:hover, .btn:hover { border-color: rgba(255,255,255,.35); }
    .lang-menu {
      position: absolute;
      right: 0;
      top: calc(100% + .55rem);
      width: 220px;
      border: 1px solid var(--line);
      background: #0f1014;
      border-radius: 14px;
      overflow: hidden;
      display: none;
      box-shadow: var(--shadow);
    }
    .lang-menu.show { display: block; }
    .lang-menu button {
      width: 100%; text-align: left;
      background: transparent; border: 0; color: #d8dce6;
      padding: .8rem .95rem; cursor: pointer;
      min-height: 44px;
    }
    .lang-menu button:hover { background: #171922; }

    .menu-btn { display: none; min-height: 44px; min-width: 44px; }

    .hero { padding: 4.5rem 0 3.2rem; }
    .hero-grid {
      display: grid;
      grid-template-columns: 1.2fr .95fr;
      gap: 1.8rem;
      align-items: stretch;
    }
    .hero-copy h1 {
      margin: .7rem 0 1.15rem;
      font-size: clamp(2.4rem, 1.5rem + 3vw, 5rem);
      line-height: .95;
      letter-spacing: -.03em;
      max-width: 15ch;
    }
    .hero-copy p { color: #bcc2cf; max-width: 56ch; }
    .hero-actions { margin-top: 1.4rem; display: flex; gap: .75rem; flex-wrap: wrap; }
    .btn.primary {
      background: linear-gradient(135deg, var(--accent), #2e75f3);
      border-color: transparent;
      color: #fff;
    }

    .hero-carousel {
      border: 1px solid var(--line);
      border-radius: var(--r-lg);
      padding: 1.1rem;
      background: linear-gradient(160deg, #111319 0%, #101216 45%, #0e1015 100%);
      display: grid;
      grid-template-rows: 1fr auto;
      min-height: 470px;
      box-shadow: var(--shadow);
    }
    .hero-slides { position: relative; overflow: hidden; border-radius: 16px; }
    .hero-slide {
      position: absolute; inset: 0;
      opacity: 0; transform: translateX(20px);
      transition: opacity .45s ease, transform .45s ease;
      border-radius: 16px;
      overflow: hidden;
      border: 1px solid rgba(255,255,255,.06);
      background: #121620;
    }
    .hero-slide.active { opacity: 1; transform: translateX(0); }
    .hero-slide img { width: 100%; height: 58%; object-fit: cover; filter: saturate(.8) contrast(1.05); }
    .hero-card { padding: 1rem 1rem 1.15rem; }
    .hero-card h3 { margin: .45rem 0 .4rem; font-size: 1.15rem; line-height: 1.25; }
    .hero-card p { margin: 0; color: #c0c5d2; font-size: .94rem; }
    .hero-controls { display: flex; justify-content: space-between; align-items: center; padding-top: .9rem; }
    .dots { display: flex; gap: .45rem; }
    .dot {
      width: 10px; height: 10px; border-radius: 50%; border: 0;
      background: #3a3f4b; cursor: pointer;
    }
    .dot.active { background: var(--accent); }
    .hero-nav button, .carousel-btn {
      border: 1px solid rgba(255,255,255,.18);
      background: #121419;
      color: #eff2f9;
      width: 42px; height: 42px;
      border-radius: 50%;
      cursor: pointer;
      min-height: 42px;
      transition: .2s ease;
    }
    .hero-nav button:hover, .carousel-btn:hover { border-color: rgba(255,255,255,.45); }

    .panel {
      border: 1px solid var(--line);
      border-radius: var(--r-lg);
      background: linear-gradient(145deg, #111319, #0f1116);
      box-shadow: var(--shadow);
    }

    .team-wrap { padding: 2rem; }
    .region-tabs { display: flex; gap: .55rem; flex-wrap: wrap; margin: 1.1rem 0 1.15rem; }
    .region-tab {
      border: 1px solid #2b303b;
      background: #171922;
      color: #d3d8e3;
      padding: .55rem .95rem;
      border-radius: 999px;
      cursor: pointer;
      min-height: 44px;
    }
    .region-tab.active {
      background: linear-gradient(130deg, rgba(77,163,255,.2), rgba(77,163,255,.08));
      border-color: rgba(77,163,255,.5);
      color: #fff;
    }

    .team-carousel-window { overflow: hidden; }
    .team-track {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: calc(33.333% - .65rem);
      gap: .95rem;
      transition: transform .4s ease;
      will-change: transform;
      touch-action: pan-y;
    }
    .member-card {
      border: 1px solid #262a35;
      border-radius: var(--r-md);
      overflow: hidden;
      background: #12151c;
      min-height: 420px;
      display: grid;
      grid-template-rows: 220px 1fr;
    }
    .member-card img { width: 100%; height: 100%; object-fit: cover; filter: grayscale(.1) contrast(1.05); }
    .member-body { padding: .95rem .95rem 1.05rem; display: grid; align-content: start; gap: .45rem; }
    .member-body blockquote {
      margin: 0;
      font-size: .95rem;
      color: #d7dbe5;
      line-height: 1.45;
      min-height: 74px;
    }
    .member-meta { color: #aeb4c2; font-size: .89rem; }
    .office-link { color: #8fc2ff; font-size: .89rem; }

    .team-controls { display: flex; justify-content: space-between; align-items: center; margin-top: 1rem; }

    .work-row {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(260px, 350px);
      gap: 1rem;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      padding-bottom: .4rem;
    }
    .work-card {
      scroll-snap-align: start;
      border: 1px solid #2b2f3a;
      border-radius: var(--r-md);
      overflow: hidden;
      background: #11141a;
      min-height: 320px;
    }
    .work-card img { width: 100%; height: 196px; object-fit: cover; filter: saturate(.8); }
    .work-card h3 { margin: .9rem .9rem .55rem; font-size: 1.08rem; line-height: 1.3; }
    .work-card p { margin: 0 .9rem 1.1rem; color: #bbc1ce; font-size: .92rem; }

    .cta {
      text-align: center;
      padding: 4.2rem 1.3rem;
      background:
        radial-gradient(900px 350px at 25% 10%, rgba(255,180,84,.12), transparent 60%),
        linear-gradient(145deg, #13161f, #101217);
      border: 1px solid #2a2d38;
      border-radius: 24px;
    }
    .cta h3 { font-size: clamp(1.5rem, 1rem + 1.8vw, 2.7rem); margin: 0 0 .75rem; line-height: 1.1; }
    .cta p { color: #c1c6d1; max-width: 60ch; margin: 0 auto 1.4rem; }

    .grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
    .grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }

    .card {
      border: 1px solid #2a2f3b;
      border-radius: var(--r-md);
      background: #10131a;
      overflow: hidden;
      min-height: 100%;
    }
    .card img { width: 100%; height: 170px; object-fit: cover; }
    .card .body { padding: .9rem; }
    .card h4 { margin: 0 0 .45rem; font-size: 1.02rem; line-height: 1.35; }
    .card p { margin: 0; color: #bcc2cd; font-size: .92rem; }

    .principle {
      border: 1px solid #29303a;
      border-radius: var(--r-md);
      padding: 1rem;
      background: linear-gradient(180deg, #131721, #0f1117);
    }
    .principle h4 { margin: .1rem 0 .5rem; font-size: 1.04rem; }
    .principle p { margin: 0; color: #b7bfcb; font-size: .92rem; }

    footer { border-top: 1px solid #222732; padding: 2rem 0 2.4rem; }
    .footer-grid { display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap; color: #a6adba; font-size: .9rem; }

    .cookie {
      position: fixed; left: 1rem; right: 1rem; bottom: 1rem;
      max-width: 920px; margin-inline: auto;
      border: 1px solid #2a2f3a;
      border-radius: 14px;
      padding: .95rem;
      background: rgba(14,16,22,.95);
      backdrop-filter: blur(8px);
      z-index: 80;
      display: none;
    }
    .cookie.show { display: block; }
    .cookie-row { display: flex; gap: .8rem; justify-content: space-between; align-items: center; flex-wrap: wrap; }
    .cookie p { margin: 0; color: #c2c8d4; font-size: .9rem; max-width: 60ch; }
    .cookie-actions { display: flex; gap: .45rem; flex-wrap: wrap; }

    @media (max-width: 1080px) {
      .hero-grid { grid-template-columns: 1fr; }
      .team-track { grid-auto-columns: calc(50% - .5rem); }
      .grid-4 { grid-template-columns: repeat(2, 1fr); }
      .grid-3 { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 820px) {
      .container { width: min(var(--max), calc(100% - 1.2rem)); }
      .nav-links {
        position: absolute;
        left: .8rem; right: .8rem; top: 74px;
        border: 1px solid #272c36;
        border-radius: 14px;
        background: #0f1218;
        padding: .7rem;
        display: none;
        flex-direction: column;
        align-items: flex-start;
      }
      .nav-links.show { display: flex; }
      .menu-btn { display: inline-flex; align-items: center; justify-content: center; }
      .desktop-only { display: none; }
      .hero-carousel { min-height: 430px; }
      .team-wrap { padding: 1rem; }
      .team-track { grid-auto-columns: 100%; }
      .grid-3, .grid-4 { grid-template-columns: 1fr; }
      .section { padding: 4rem 0; }
    }

    @media (prefers-reduced-motion: reduce) {
      * { animation-duration: .001ms !important; transition-duration: .001ms !important; scroll-behavior: auto !important; }
    }
  </style>
</head>
<body>
  <header class="header">
    <div class="container nav">
      <a href="#home" class="brand" aria-label="Leap Studio Home">
        <span class="brand-mark" aria-hidden="true"></span>
        <span>Leap Studio</span>
      </a>

      <button class="menu-btn lang-btn" id="menuToggle" aria-expanded="false" aria-controls="navLinks" aria-label="Open menu">☰</button>

      <nav id="navLinks" class="nav-links" aria-label="Primary navigation">
        <a href="#insights">Insights</a>
        <a href="#work">Work</a>
        <a href="#services">Services</a>
        <a href="#culture">Culture</a>
        <a href="#mark">Make Your Mark</a>
        <a href="#contact">Contact Us</a>
      </nav>

      <div class="lang-wrap desktop-only">
        <button class="lang-btn" id="langBtn" aria-haspopup="true" aria-expanded="false">Global EN ▾</button>
        <div class="lang-menu" id="langMenu" role="menu" aria-label="Language options">
          <button role="menuitem">Global EN</button>
          <button role="menuitem">France FR</button>
          <button role="menuitem">China CN</button>
        </div>
      </div>
    </div>
  </header>

  <main id="home">
    <section class="hero container" id="services">
      <div class="hero-grid">
        <div class="hero-copy">
          <span class="eyebrow">Reinvention & Experience Partner</span>
          <h1>We Design What Enterprise Becomes Next.</h1>
          <p>Leap Studio helps global organizations turn complexity into magnetic experiences. We fuse strategy, design, and technology to unlock growth, culture change, and measurable business impact at scale.</p>
          <div class="hero-actions">
            <a class="btn primary" href="#work">Explore Our Work</a>
            <a class="btn" href="#contact">Start a Conversation</a>
          </div>
        </div>

        <div class="hero-carousel" aria-label="Featured content carousel">
          <div class="hero-slides" id="heroSlides"></div>
          <div class="hero-controls">
            <div class="dots" id="heroDots" aria-label="Slide indicators"></div>
            <div class="hero-nav">
              <button id="heroPrev" aria-label="Previous hero slide">←</button>
              <button id="heroNext" aria-label="Next hero slide">→</button>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="culture">
      <div class="container panel team-wrap">
        <span class="eyebrow">Global Studios</span>
        <h2 class="h2">Teams that move across continents and cultures.</h2>
        <p class="lead">From New York to Melbourne, our multidisciplinary teams partner with enterprise leaders to shape products, services, and brands that feel deeply human and globally relevant.</p>

        <div class="region-tabs" id="regionTabs" role="tablist" aria-label="Team regions"></div>

        <div class="team-carousel-window">
          <div class="team-track" id="teamTrack" aria-live="polite"></div>
        </div>

        <div class="team-controls">
          <p id="teamRegionLabel" style="margin:0;color:#b8becb">North America Team</p>
          <div>
            <button class="carousel-btn" id="teamPrev" aria-label="Previous team member">←</button>
            <button class="carousel-btn" id="teamNext" aria-label="Next team member">→</button>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="work">
      <div class="container">
        <span class="eyebrow">Client Work</span>
        <h2 class="h2">Outcomes that earn loyalty, speed, and growth.</h2>
        <div class="work-row" id="workRow" aria-label="Featured case studies"></div>
      </div>
    </section>

    <section class="section" id="mark">
      <div class="container">
        <div class="cta">
          <span class="eyebrow">Make Your Mark</span>
          <h3>Build the next era of your category.</h3>
          <p>We partner with ambitious brand and innovation leaders to reinvent customer journeys, operating models, and growth platforms—end to end.</p>
          <a href="#contact" class="btn primary">Let’s Create Together</a>
        </div>
      </div>
    </section>

    <section class="section" id="how-we-work">
      <div class="container">
        <span class="eyebrow">How We Work</span>
        <h2 class="h2">Strategy, design, and delivery in one integrated model.</h2>
        <div class="grid-3" id="howGrid"></div>
      </div>
    </section>

    <section class="section" id="insights">
      <div class="container">
        <span class="eyebrow">Latest Insights</span>
        <h2 class="h2">Signals shaping the future of experience.</h2>
        <div class="grid-3" id="insightsGrid"></div>
      </div>
    </section>

    <section class="section" id="principles">
      <div class="container">
        <span class="eyebrow">Our Principles</span>
        <h2 class="h2">How we show up in every partnership.</h2>
        <div class="grid-4" id="principlesGrid"></div>
      </div>
    </section>
  </main>

  <footer id="contact">
    <div class="container footer-grid">
      <div>© 2026 Leap Studio. Reinventing enterprise experiences worldwide.</div>
      <div>Studios: New York · San Francisco · London · Munich · Singapore · Melbourne</div>
    </div>
  </footer>

  <aside class="cookie show" id="cookieBanner" aria-live="polite">
    <div class="cookie-row">
      <p>We use cookies to improve site performance, personalize content, and understand visitor behavior. You can accept all, decline all, or manage your settings.</p>
      <div class="cookie-actions">
        <button class="btn primary" id="cookieAccept">Accept All</button>
        <button class="btn" id="cookieManage">Manage Settings</button>
        <button class="btn" id="cookieDecline">Decline All</button>
      </div>
    </div>
  </aside>

  <script>
    const heroData = [
      {
        type: 'Report',
        title: 'When Human Connection Meets AI',
        text: 'A field guide for enterprise teams building trust, relevance, and speed with AI-augmented experiences.',
        image: 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=1300&q=80'
      },
      {
        type: 'Project Highlight',
        title: 'Modernizing the Point-of-Sale Experience',
        text: 'A full-stack redesign helping frontline teams move faster while making every customer moment feel seamless.',
        image: 'https://images.unsplash.com/photo-1504384308090-c894fdcc538d?auto=format&fit=crop&w=1300&q=80'
      },
      {
        type: 'Podcast',
        title: 'Writing the Future of AI',
        text: 'Leaders discuss responsible innovation and the new capabilities required to scale impact across the enterprise.',
        image: 'https://images.unsplash.com/photo-1551836022-deb4988cc6c0?auto=format&fit=crop&w=1300&q=80'
      }
    ];

    const teamByRegion = {
      'North America': [
        { name: 'Maya Chen', title: 'Principal Experience Strategist', office: 'New York', quote: 'Enterprise change succeeds when strategy and story move together.', image: 'https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?auto=format&fit=crop&w=900&q=80' },
        { name: 'Jordan Ellis', title: 'Executive Creative Director', office: 'San Francisco', quote: 'The best systems feel invisible—until they create unforgettable moments.', image: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=900&q=80' },
        { name: 'Ariana Brooks', title: 'VP, Innovation Partnerships', office: 'New York', quote: 'We align bold ideas with enterprise realities and still move fast.', image: 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=900&q=80' }
      ],
      'Asia': [
        { name: 'Ravi Menon', title: 'Director, Service Design', office: 'Singapore', quote: 'Precision and empathy are not opposites—they are multipliers.', image: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=900&q=80' },
        { name: 'Yuna Park', title: 'Head of Experience Operations', office: 'Singapore', quote: 'Global consistency works best when local context is designed in.', image: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=900&q=80' },
        { name: 'Wei Lin', title: 'Client Partner, Enterprise Growth', office: 'Singapore', quote: 'We translate complexity into decisions teams can act on now.', image: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=900&q=80' }
      ],
      'Europe': [
        { name: 'Elena Fischer', title: 'Managing Director, Experience', office: 'Munich', quote: 'Craft and velocity can coexist when teams share a common north star.', image: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=900&q=80' },
        { name: 'Theo Martin', title: 'Head of Product Design', office: 'London', quote: 'Design is the bridge between ambition and operational truth.', image: 'https://images.unsplash.com/photo-1463453091185-61582044d556?auto=format&fit=crop&w=900&q=80' },
        { name: 'Sofia Adler', title: 'Lead Research Partner', office: 'London', quote: 'Insight becomes advantage when it changes what teams do next.', image: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=900&q=80' }
      ],
      'Oceania': [
        { name: 'Noah Bennett', title: 'Studio Lead, Transformation', office: 'Melbourne', quote: 'We build momentum by making strategy tangible in every sprint.', image: 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?auto=format&fit=crop&w=900&q=80' },
        { name: 'Olivia Hart', title: 'Design Director', office: 'Melbourne', quote: 'A premium experience is a thousand thoughtful details aligned.', image: 'https://images.unsplash.com/photo-1542204625-de293a06df38?auto=format&fit=crop&w=900&q=80' },
        { name: 'Kai Thompson', title: 'Senior Experience Architect', office: 'Melbourne', quote: 'Our role is turning bold narratives into operating reality.', image: 'https://images.unsplash.com/photo-1504593811423-6dd665756598?auto=format&fit=crop&w=900&q=80' }
      ]
    };

    const workItems = [
      'Creating Consumer Insights at Scale',
      'Deepening Customer Engagement',
      'Harnessing Data for Leaner and Greener Future of Mobility',
      'Modernizing the Point-of-Sale Experience',
      'Reimagining Luxury Craftsmanship',
      'Helping Healthier Habits Stick'
    ].map((title, index) => ({
      title,
      text: 'A cross-functional engagement blending strategy, design, and technology to deliver measurable enterprise value.',
      image: [
