            <p>${item.text}</p>
          </div>
        </article>
      `).join('');

      heroDots.innerHTML = heroData.map((_, i) => `<button class="dot ${i === heroIndex ? 'active' : ''}" aria-label="Go to slide ${i + 1}" data-slide="${i}"></button>`).join('');
    }

    function setHero(index) {
      heroIndex = (index + heroData.length) % heroData.length;
      renderHero();
      restartHeroAuto();
    }

    function restartHeroAuto() {
      clearInterval(heroTimer);
      heroTimer = setInterval(() => setHero(heroIndex + 1), 5600);
    }

    document.getElementById('heroPrev').addEventListener('click', () => setHero(heroIndex - 1));
    document.getElementById('heroNext').addEventListener('click', () => setHero(heroIndex + 1));
