          'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=900&q=80',
          'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=900&q=80',
          'https://images.unsplash.com/photo-1581090700227-1e8e8c8f0f9d?auto=format&fit=crop&w=900&q=80',
          'https://images.unsplash.com/photo-1520607162513-77705c0f0d4a?auto=format&fit=crop&w=900&q=80'
        ][i]}" alt="${title}" loading="lazy" />
        <div class="body">
          <h4>${title}</h4>
          <p>Read the perspective →</p>
        </div>
      </article>
    `).join('');

    const principlesGrid = document.getElementById('principlesGrid');
    principlesGrid.innerHTML = principles.map(item => `
      <article class="principle">
        <h4>${item.title}</h4>
        <p>${item.text}</p>
      </article>
    `).join('');

    const howGrid = document.getElementById('howGrid');
    howGrid.innerHTML = howWeWork.map(step => `
      <article class="card">
        <img src="${step.image}" alt="${step.title}" loading="lazy" />
        <div class="body">
          <h4>${step.title}</h4>
          <p>${step.text}</p>
        </div>
      </article>
    `).join('');

    const langBtn = document.getElementById('langBtn');
    const langMenu = document.getElementById('langMenu');
    langBtn?.addEventListener('click', () => {
      const show = !langMenu.classList.contains('show');
      langMenu.classList.toggle('show', show);
      langBtn.setAttribute('aria-expanded', String(show));
    });
    document.addEventListener('click', (e) => {
      if (!langBtn || !langMenu) return;
      if (!langMenu.contains(e.target) && !langBtn.contains(e.target)) {
        langMenu.classList.remove('show');
        langBtn.setAttribute('aria-expanded', 'false');
      }
    });

    document.getElementById('cookieAccept').addEventListener('click', () => {
      localStorage.setItem('leap-cookie', 'accept');
      document.getElementById('cookieBanner').classList.remove('show');
    });
    document.getElementById('cookieDecline').addEventListener('click', () => {
      localStorage.setItem('leap-cookie', 'decline');
      document.getElementById('cookieBanner').classList.remove('show');
    });
    document.getElementById('cookieManage').addEventListener('click', () => {
      alert('Cookie preferences center is coming soon.');
    });
    if (localStorage.getItem('leap-cookie')) {
      document.getElementById('cookieBanner').classList.remove('show');
    }

    const menuToggle = document.getElementById('menuToggle');
    const navLinks = document.getElementById('navLinks');
    menuToggle.addEventListener('click', () => {
      const show = !navLinks.classList.contains('show');
      navLinks.classList.toggle('show', show);
      menuToggle.setAttribute('aria-expanded', String(show));
    });
  </script>
</body>
