    }
  </style>
</head>
<body>
  <header class="header">
    <div class="container nav">
      <a href="#home" class="brand" aria-label="Leap Studio Home">
        <span class="brand-mark" aria-hidden="true"></span>
        <span>Leap Studio</span>
      </a>

      <button class="menu-btn lang-btn" id="menuToggle" aria-expanded="false" aria-controls="navLinks" aria-label="Open menu">☰</button>

      <nav id="navLinks" class="nav-links" aria-label="Primary navigation">
        <a href="#insights">Insights</a>
        <a href="#work">Work</a>
        <a href="#services">Services</a>
        <a href="#culture">Culture</a>
        <a href="#mark">Make Your Mark</a>
        <a href="#contact">Contact Us</a>
      </nav>

      <div class="lang-wrap desktop-only">
        <button class="lang-btn" id="langBtn" aria-haspopup="true" aria-expanded="false">Global EN ▾</button>
        <div class="lang-menu" id="langMenu" role="menu" aria-label="Language options">
          <button role="menuitem">Global EN</button>
          <button role="menuitem">France FR</button>
          <button role="menuitem">China CN</button>
        </div>
      </div>
    </div>
  </header>

  <main id="home">
    <section class="hero container" id="services">
      <div class="hero-grid">
        <div class="hero-copy">
          <span class="eyebrow">Reinvention & Experience Partner</span>
          <h1>We Design What Enterprise Becomes Next.</h1>
          <p>Leap Studio helps global organizations turn complexity into magnetic experiences. We fuse strategy, design, and technology to unlock growth, culture change, and measurable business impact at scale.</p>
          <div class="hero-actions">
            <a class="btn primary" href="#work">Explore Our Work</a>
            <a class="btn" href="#contact">Start a Conversation</a>
          </div>
        </div>

        <div class="hero-carousel" aria-label="Featured content carousel">
          <div class="hero-slides" id="heroSlides"></div>
          <div class="hero-controls">
            <div class="dots" id="heroDots" aria-label="Slide indicators"></div>
            <div class="hero-nav">
              <button id="heroPrev" aria-label="Previous hero slide">←</button>
              <button id="heroNext" aria-label="Next hero slide">→</button>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="culture">
      <div class="container panel team-wrap">
        <span class="eyebrow">Global Studios</span>
        <h2 class="h2">Teams that move across continents and cultures.</h2>
        <p class="lead">From New York to Melbourne, our multidisciplinary teams partner with enterprise leaders to shape products, services, and brands that feel deeply human and globally relevant.</p>

        <div class="region-tabs" id="regionTabs" role="tablist" aria-label="Team regions"></div>

        <div class="team-carousel-window">
          <div class="team-track" id="teamTrack" aria-live="polite"></div>
        </div>

        <div class="team-controls">
          <p id="teamRegionLabel" style="margin:0;color:#b8becb">North America Team</p>
          <div>
            <button class="carousel-btn" id="teamPrev" aria-label="Previous team member">←</button>
            <button class="carousel-btn" id="teamNext" aria-label="Next team member">→</button>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="work">
      <div class="container">
        <span class="eyebrow">Client Work</span>
        <h2 class="h2">Outcomes that earn loyalty, speed, and growth.</h2>
        <div class="work-row" id="workRow" aria-label="Featured case studies"></div>
      </div>
    </section>

    <section class="section" id="mark">
      <div class="container">
        <div class="cta">
          <span class="eyebrow">Make Your Mark</span>
          <h3>Build the next era of your category.</h3>
          <p>We partner with ambitious brand and innovation leaders to reinvent customer journeys, operating models, and growth platforms—end to end.</p>
          <a href="#contact" class="btn primary">Let’s Create Together</a>
        </div>
      </div>
    </section>

    <section class="section" id="how-we-work">
      <div class="container">
        <span class="eyebrow">How We Work</span>
        <h2 class="h2">Strategy, design, and delivery in one integrated model.</h2>
        <div class="grid-3" id="howGrid"></div>
      </div>
    </section>

    <section class="section" id="insights">
      <div class="container">
        <span class="eyebrow">Latest Insights</span>
        <h2 class="h2">Signals shaping the future of experience.</h2>
        <div class="grid-3" id="insightsGrid"></div>
      </div>
    </section>

    <section class="section" id="principles">
      <div class="container">
        <span class="eyebrow">Our Principles</span>
        <h2 class="h2">How we show up in every partnership.</h2>
        <div class="grid-4" id="principlesGrid"></div>
      </div>
    </section>
  </main>

  <footer id="contact">
    <div class="container footer-grid">
      <div>© 2026 Leap Studio. Reinventing enterprise experiences worldwide.</div>
      <div>Studios: New York · San Francisco · London · Munich · Singapore · Melbourne</div>
    </div>
  </footer>

  <aside class="cookie show" id="cookieBanner" aria-live="polite">
    <div class="cookie-row">
      <p>We use cookies to improve site performance, personalize content, and understand visitor behavior. You can accept all, decline all, or manage your settings.</p>
      <div class="cookie-actions">
        <button class="btn primary" id="cookieAccept">Accept All</button>
        <button class="btn" id="cookieManage">Manage Settings</button>
        <button class="btn" id="cookieDecline">Decline All</button>
      </div>
    </div>
  </aside>

  <script>
    const heroData = [
      {
        type: 'Report',
        title: 'When Human Connection Meets AI',
        text: 'A field guide for enterprise teams building trust, relevance, and speed with AI-augmented experiences.',
        image: 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=1300&q=80'
      },
      {
        type: 'Project Highlight',
        title: 'Modernizing the Point-of-Sale Experience',
        text: 'A full-stack redesign helping frontline teams move faster while making every customer moment feel seamless.',
        image: 'https://images.unsplash.com/photo-1504384308090-c894fdcc538d?auto=format&fit=crop&w=1300&q=80'
      },
      {
        type: 'Podcast',
        title: 'Writing the Future of AI',
        text: 'Leaders discuss responsible innovation and the new capabilities required to scale impact across the enterprise.',
        image: 'https://images.unsplash.com/photo-1551836022-deb4988cc6c0?auto=format&fit=crop&w=1300&q=80'
      }
    ];

    const teamByRegion = {
      'North America': [
        { name: 'Maya Chen', title: 'Principal Experience Strategist', office: 'New York', quote: 'Enterprise change succeeds when strategy and story move together.', image: 'https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?auto=format&fit=crop&w=900&q=80' },
        { name: 'Jordan Ellis', title: 'Executive Creative Director', office: 'San Francisco', quote: 'The best systems feel invisible—until they create unforgettable moments.', image: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=900&q=80' },
        { name: 'Ariana Brooks', title: 'VP, Innovation Partnerships', office: 'New York', quote: 'We align bold ideas with enterprise realities and still move fast.', image: 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=900&q=80' }
      ],
      'Asia': [
        { name: 'Ravi Menon', title: 'Director, Service Design', office: 'Singapore', quote: 'Precision and empathy are not opposites—they are multipliers.', image: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=900&q=80' },
        { name: 'Yuna Park', title: 'Head of Experience Operations', office: 'Singapore', quote: 'Global consistency works best when local context is designed in.', image: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=900&q=80' },
        { name: 'Wei Lin', title: 'Client Partner, Enterprise Growth', office: 'Singapore', quote: 'We translate complexity into decisions teams can act on now.', image: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=900&q=80' }
      ],
      'Europe': [
        { name: 'Elena Fischer', title: 'Managing Director, Experience', office: 'Munich', quote: 'Craft and velocity can coexist when teams share a common north star.', image: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=900&q=80' },
        { name: 'Theo Martin', title: 'Head of Product Design', office: 'London', quote: 'Design is the bridge between ambition and operational truth.', image: 'https://images.unsplash.com/photo-1463453091185-61582044d556?auto=format&fit=crop&w=900&q=80' },
        { name: 'Sofia Adler', title: 'Lead Research Partner', office: 'London', quote: 'Insight becomes advantage when it changes what teams do next.', image: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=900&q=80' }
      ],
      'Oceania': [
        { name: 'Noah Bennett', title: 'Studio Lead, Transformation', office: 'Melbourne', quote: 'We build momentum by making strategy tangible in every sprint.', image: 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?auto=format&fit=crop&w=900&q=80' },
        { name: 'Olivia Hart', title: 'Design Director', office: 'Melbourne', quote: 'A premium experience is a thousand thoughtful details aligned.', image: 'https://images.unsplash.com/photo-1542204625-de293a06df38?auto=format&fit=crop&w=900&q=80' },
        { name: 'Kai Thompson', title: 'Senior Experience Architect', office: 'Melbourne', quote: 'Our role is turning bold narratives into operating reality.', image: 'https://images.unsplash.com/photo-1504593811423-6dd665756598?auto=format&fit=crop&w=900&q=80' }
      ]
    };

    const workItems = [
      'Creating Consumer Insights at Scale',
      'Deepening Customer Engagement',
      'Harnessing Data for Leaner and Greener Future of Mobility',
      'Modernizing the Point-of-Sale Experience',
      'Reimagining Luxury Craftsmanship',
      'Helping Healthier Habits Stick'
    ].map((title, index) => ({
      title,
      text: 'A cross-functional engagement blending strategy, design, and technology to deliver measurable enterprise value.',
      image: [
        'https://images.unsplash.com/photo-1498050108023-c5249f4df085?auto=format&fit=crop&w=1100&q=80',
        'https://images.unsplash.com/photo-1556740758-90de374c12ad?auto=format&fit=crop&w=1100&q=80',
        'https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&fit=crop&w=1100&q=80',
        'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=1100&q=80',
        'https://images.unsplash.com/photo-1521572267360-ee0c2909d518?auto=format&fit=crop&w=1100&q=80',
        'https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=1100&q=80'
      ][index]
    }));

    const insights = [
      'When Human Connection Meets AI',
      'Writing the Future of AI',
      'Amplifying Clinical Care with AI',
      'The Future of Customer Experience',
      'Next-Gen Contact Centers: Powered by AI',
      'From Complexity to Clarity'
    ];

    const principles = [
      { title: 'Challenge the status quo', text: 'We question inherited assumptions and open new strategic options.' },
      { title: 'Fuse art & science to make ideas real', text: 'We blend creative craft with rigorous delivery to move from vision to outcomes.' },
      { title: 'Create a lasting impact at global scale', text: 'Our work is designed for adoption across geographies, functions, and cultures.' },
      { title: 'Regenerate systems & communities', text: 'We build responsibly, creating value for business, people, and the broader ecosystem.' }
    ];

    const howWeWork = [
      { title: 'Discover & Frame', text: 'Define the challenge, align stakeholders, and establish measurable ambition.', image: 'https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=900&q=80' },
      { title: 'Design & Prototype', text: 'Create future-state service, product, and brand experiences with real user signal.', image: 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=900&q=80' },
      { title: 'Scale & Sustain', text: 'Operationalize the experience through governance, capability uplift, and tooling.', image: 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?auto=format&fit=crop&w=900&q=80' }
    ];

    const heroSlides = document.getElementById('heroSlides');
    const heroDots = document.getElementById('heroDots');
    let heroIndex = 0;
    let heroTimer;

    function renderHero() {
      heroSlides.innerHTML = heroData.map((item, i) => `
        <article class="hero-slide ${i === heroIndex ? 'active' : ''}" aria-hidden="${i === heroIndex ? 'false' : 'true'}">
          <img src="${item.image}" alt="${item.title}" loading="lazy" />
          <div class="hero-card">
            <span class="eyebrow">${item.type}</span>
            <h3>${item.title}</h3>
            <p>${item.text}</p>
          </div>
        </article>
      `).join('');

      heroDots.innerHTML = heroData.map((_, i) => `<button class="dot ${i === heroIndex ? 'active' : ''}" aria-label="Go to slide ${i + 1}" data-slide="${i}"></button>`).join('');
    }

    function setHero(index) {
      heroIndex = (index + heroData.length) % heroData.length;
      renderHero();
      restartHeroAuto();
    }

    function restartHeroAuto() {
      clearInterval(heroTimer);
      heroTimer = setInterval(() => setHero(heroIndex + 1), 5600);
    }

    document.getElementById('heroPrev').addEventListener('click', () => setHero(heroIndex - 1));
    document.getElementById('heroNext').addEventListener('click', () => setHero(heroIndex + 1));
    heroDots.addEventListener('click', (e) => {
      if (e.target.matches('.dot')) setHero(Number(e.target.dataset.slide));
    });

    renderHero();
    restartHeroAuto();

    const regionTabs = document.getElementById('regionTabs');
    const teamTrack = document.getElementById('teamTrack');
    const teamLabel = document.getElementById('teamRegionLabel');
    const regions = ['North America', 'Asia', 'Europe', 'Oceania'];
    let activeRegion = 'North America';
    let teamIndex = 0;

    function cardsPerView() {
      if (window.innerWidth <= 820) return 1;
      if (window.innerWidth <= 1080) return 2;
      return 3;
    }

    function renderTeamTabs() {
      regionTabs.innerHTML = regions.map(region => `
        <button class="region-tab ${region === activeRegion ? 'active' : ''}" role="tab" aria-selected="${region === activeRegion}" data-region="${region}">${region}</button>
      `).join('');
    }

    function renderTeamCards() {
      const members = teamByRegion[activeRegion];
      teamTrack.style.transform = 'translateX(0)';
      teamIndex = 0;
      teamLabel.textContent = `${activeRegion} Team`;
      teamTrack.innerHTML = members.map(member => `
        <article class="member-card">
          <img src="${member.image}" alt="${member.name} portrait" loading="lazy" />
          <div class="member-body">
            <blockquote>“${member.quote}”</blockquote>
            <strong>${member.name}</strong>
            <div class="member-meta">${member.title}</div>
            <a class="office-link" href="#contact">${member.office} Office ↗</a>
          </div>
        </article>
      `).join('');
      updateTeamTransform();
    }

    function updateTeamTransform() {
      const perView = cardsPerView();
      const total = teamByRegion[activeRegion].length;
      const maxIndex = Math.max(0, total - perView);
      teamIndex = Math.min(teamIndex, maxIndex);
      const offset = (100 / perView) * teamIndex;
      teamTrack.style.transform = `translateX(-${offset}%)`;
    }

    regionTabs.addEventListener('click', (e) => {
      if (!e.target.matches('.region-tab')) return;
      activeRegion = e.target.dataset.region;
      renderTeamTabs();
      renderTeamCards();
    });

    document.getElementById('teamPrev').addEventListener('click', () => {
      teamIndex = Math.max(0, teamIndex - 1);
      updateTeamTransform();
    });

    document.getElementById('teamNext').addEventListener('click', () => {
      const maxIndex = Math.max(0, teamByRegion[activeRegion].length - cardsPerView());
      teamIndex = Math.min(maxIndex, teamIndex + 1);
      updateTeamTransform();
    });

    let dragStart = null;
    teamTrack.addEventListener('touchstart', (e) => { dragStart = e.changedTouches[0].clientX; }, { passive: true });
    teamTrack.addEventListener('touchend', (e) => {
      if (dragStart === null) return;
      const dx = e.changedTouches[0].clientX - dragStart;
      if (Math.abs(dx) > 35) {
        if (dx > 0) document.getElementById('teamPrev').click();
        else document.getElementById('teamNext').click();
      }
      dragStart = null;
    }, { passive: true });

    renderTeamTabs();
    renderTeamCards();
    window.addEventListener('resize', updateTeamTransform);

    const workRow = document.getElementById('workRow');
    workRow.innerHTML = workItems.map(item => `
      <article class="work-card">
        <img src="${item.image}" alt="${item.title}" loading="lazy" />
        <h3>${item.title}</h3>
        <p>${item.text}</p>
      </article>
    `).join('');

    const insightsGrid = document.getElementById('insightsGrid');
    insightsGrid.innerHTML = insights.map((title, i) => `
      <article class="card">
        <img src="${[
          'https://images.unsplash.com/photo-1504384308090-c894fdcc538d?auto=format&fit=crop&w=900&q=80',
          'https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=80',
          'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=900&q=80',
          'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=900&q=80',
          'https://images.unsplash.com/photo-1581090700227-1e8e8c8f0f9d?auto=format&fit=crop&w=900&q=80',
          'https://images.unsplash.com/photo-1520607162513-77705c0f0d4a?auto=format&fit=crop&w=900&q=80'
        ][i]}" alt="${title}" loading="lazy" />
        <div class="body">
          <h4>${title}</h4>
          <p>Read the perspective →</p>
        </div>
      </article>
    `).join('');

    const principlesGrid = document.getElementById('principlesGrid');
    principlesGrid.innerHTML = principles.map(item => `
      <article class="principle">
        <h4>${item.title}</h4>
        <p>${item.text}</p>
      </article>
    `).join('');

    const howGrid = document.getElementById('howGrid');
    howGrid.innerHTML = howWeWork.map(step => `
      <article class="card">
        <img src="${step.image}" alt="${step.title}" loading="lazy" />
        <div class="body">
          <h4>${step.title}</h4>
          <p>${step.text}</p>
        </div>
      </article>
    `).join('');

    const langBtn = document.getElementById('langBtn');
    const langMenu = document.getElementById('langMenu');
    langBtn?.addEventListener('click', () => {
      const show = !langMenu.classList.contains('show');
      langMenu.classList.toggle('show', show);
      langBtn.setAttribute('aria-expanded', String(show));
    });
    document.addEventListener('click', (e) => {
      if (!langBtn || !langMenu) return;
      if (!langMenu.contains(e.target) && !langBtn.contains(e.target)) {
        langMenu.classList.remove('show');
        langBtn.setAttribute('aria-expanded', 'false');
      }
    });

    document.getElementById('cookieAccept').addEventListener('click', () => {
      localStorage.setItem('leap-cookie', 'accept');
      document.getElementById('cookieBanner').classList.remove('show');
    });
    document.getElementById('cookieDecline').addEventListener('click', () => {
      localStorage.setItem('leap-cookie', 'decline');
      document.getElementById('cookieBanner').classList.remove('show');
    });
    document.getElementById('cookieManage').addEventListener('click', () => {
      alert('Cookie preferences center is coming soon.');
    });
    if (localStorage.getItem('leap-cookie')) {
      document.getElementById('cookieBanner').classList.remove('show');
    }

    const menuToggle = document.getElementById('menuToggle');
    const navLinks = document.getElementById('navLinks');
    menuToggle.addEventListener('click', () => {
      const show = !navLinks.classList.contains('show');
      navLinks.classList.toggle('show', show);
      menuToggle.setAttribute('aria-expanded', String(show));
    });
  </script>
</body>
</html>
HTML"}
